lesson.code:
students = [
    {"name": "Alice", "grades": [90, 95, 88]},
    {"name": "Bob", "grades": [78, 82, 85]}
]
for s in students:
    avg = sum(s["grades"]) / len(s["grades"])
    print(f"{s['name']} average: {avg:.1f}")

grid = [[1, 2], [3, 4]]
for row in grid:
    for val in row:
        print(val, end=" ")
    print()

catalog = {
    "electronics": ["phone", "tablet"],
    "books": ["python guide", "algorithms"]
}
for category, items in catalog.items():
    print(f"{category.title()}: {', '.join(items)}")

